            issue(`${at}.id`, "Menu item ids must be unique.");
        else
            itemIds.add(item.id);
        if (typeof item.label !== "string" || item.label.trim().length < 1 || item.label.length > 40)
            issue(`${at}.label`, "Use a label of 1–40 characters.");
